update public.principles set title = 'Borrow a category before you build one', body = '"Firebase alternative" borrowed a category developers already understood instead of inventing one.', how = 'Finish the sentence "We''re the ____ alternative" with a tool your ideal customers know. If none fits, try "____ for ____": an incumbent plus a segment it ignores.' where id = 2;
update public.principles set title = 'Own day zero', body = 'Get chosen when the project starts, then never give the project a reason to leave.', how = 'Stopwatch audit: three people who have never used your product, screen recorded, from your homepage to the first moment of real value. Do the same for your top competitor.' where id = 3;
update public.principles set title = 'Build on something you don''t own', body = 'Supabase bet on Postgres instead of building its own database, and made leaving easy: it''s just Postgres, take your data and go.', how = 'Name the open standard under or next to your product. If there isn''t one, name the open format your users'' data lives in.' where id = 4;
update public.principles set title = 'Make shipping an event, while it still works', body = 'Batch a quarter''s releases into one named Launch Week, one launch a day.', how = 'Keep a running list of everything you ship. At quarter end, pick the five best. If you can''t find five, run a launch day.' where id = 5;
