update public.principles set title = 'Free until it''s real', body = 'A generous free tier, with pricing that starts when the app has users, not while the developer is exploring.', how = 'Find your production signal: the usage pattern that means "this is real" (traffic, team size, uptime needs, data volume).' where id = 7;
update public.principles set title = 'Sales as support', body = 'Reps reach out when usage says the customer needs help (limits, errors, spikes), not when a lead score says they might buy.', how = 'Pick three triggers: near a plan limit, an error spike, usage doubling week on week.' where id = 8;
update public.principles set title = 'Be legible to AI', body = 'Supabase became the default backend for AI app builders and coding agents, which now create most of its new databases.', how = 'Ask three AI models the question your ideal customer would ask, 10 times each. Count how often you''re named, and first. That''s your baseline (our prompts and scripts are open source).' where id = 9;
update public.principles set title = 'Raise for leverage, operate like you didn''t', body = 'Supabase raised over $1B and ran it like $100K in the bank: no offices, no real ad budget, every decision written down. Copplestone''s rule: the money changes nothing about how you operate.', how = 'Before every hire, write one sentence: "This is burning, and it will keep burning without this person." If you can''t, don''t hire.' where id = 10;
update public.principles set title = 'Pick an ideal customer that grows into big bills', body = 'Supabase targeted high-growth, venture-backed startups from day one: the companies whose free projects become big production databases.', how = 'Describe your ideal customer in one sentence: who they are, the trigger that makes them look, and why their usage grows without you.' where id = 11;
update public.principles set title = 'The CEO is the channel', body = 'Copplestone read Hacker News three times a day, posted Supabase''s biggest stories himself, and kept polling developers in public.', how = 'Pick the one place your ideal customers read every day (Hacker News, a subreddit, X, a Discord) and read it daily.' where id = 12;

insert into public.start_here (n, action, why, lesson_id, takes) values
  (1, 'Run the stopwatch audit on your product and your top competitor.', 'Half a day, the cheapest growth lever you have, and the result tells you what to fix first.', 3, 'Half a day'),
  (2, 'Write your ideal-customer sentence and name 20 teams that fit.', 'If you can''t name 20, nothing downstream (positioning, content, outreach) has a target.', 11, '1 hour'),
  (3, 'Post three times this week as the founder, in the one place your ideal customers read daily.', 'Free distribution and free customer research, and it compounds.', 12, '30 minutes a day')
on conflict (n) do update set action = excluded.action, why = excluded.why, lesson_id = excluded.lesson_id, takes = excluded.takes;

insert into public.stage_playbook (sort, stage, period, supabase, you, lessons) values
  (1, 'Pre-launch', 'Dec 2019 to May 2020', 'A month of developer interviews and an ideal customer of VC-backed startups, then building. Tested the tagline before the Show HN.', 'Interview 20 developers before writing code. Write your ideal-customer sentence and name 20 teams. Run the tagline test and the stopwatch on the incumbent.', '11, 1, 2, 3'),
  (2, 'Launch to first traction', 'May 2020 to 2021', 'Show HN #1, YC S20, $6M seed, first launch week. The CEO posted the big stories himself.', 'One big launch moment built around the borrowed category. Post in public as the founder every week. Teach the standard. Start a launch cadence and measure signups, not stars.', '12, 2, 4, 5, 6'),
  (3, 'Early revenue', '2021 to 2023', 'Free until production, usage-triggered sales, launch weeks at peak lift.', 'Find your production signal and charge from it. Run founder-led triggered outreach with a control group. Know the 2026 bar: $100K to $500K ARR before a Series A.', '7, 8'),
  (4, 'Scale', '2023 onward', 'pgvector, AI app builders, coding agents. Launch weeks turn into retention.', 'Measure your AI visibility, build for agents, check which rituals still acquire users.', '5, 9'),
  (5, 'Always', 'Every stage', 'Raised over $1B and still ran it like $100K in the bank.', 'Retention before acquisition. Founder hours on user calls, however much you raise.', '10')
on conflict (sort) do update set stage = excluded.stage, period = excluded.period, supabase = excluded.supabase, you = excluded.you, lessons = excluded.lessons;

insert into public.templates (id, lesson_id, title, takes, body_md) values
  ('icp_list', 11, 'ICP sentence and 20 teams', '1 hour', '# ICP sentence and 20 teams

ICP: [who] who [trigger that makes them look], and whose usage grows because [reason].

| # | Team | Why they fit | Where they gather | Contacted | Adopted | Usage after 90 days |
| --- | --- | --- | --- | --- | --- | --- |
| 1 | | | | | | |
| 2 | | | | | | |
| 3 | | | | | | |
| ... | | | | | | |
| 20 | | | | | | |

Can''t name 20? The ICP is too narrow or too vague. Rewrite the sentence every quarter.
'),
  ('founder_channel', 12, 'Founder channel: weekly cadence', '30 minutes a day', '# Founder channel: weekly cadence

Where my ideal customers read daily: ____

| Day | Read (15 min) | Post (as yourself) | Replies answered |
| --- | --- | --- | --- |
| Mon | | What I built | |
| Tue | | | |
| Wed | | What broke and why | |
| Thu | | | |
| Fri | | What I learned | |

Monthly: signups attributed to founder posts = ____ · replies per post = ____
Quarterly: one genuinely useful post about the standard, aimed at the front page.
')
on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, takes = excluded.takes, body_md = excluded.body_md;

insert into public.dont_copy (n, title, body) values
  (5, 'Launch weeks forever', 'Measure the lift in signups, not stars, and change the format when it stops working. Supabase''s star lift fell every year.'),
  (6, 'Free until real, in 2026 money', 'Supabase earned roughly nothing for 18 months on 2020 and 2021 money. Today a seed-to-Series A raise typically expects $100K to $500K ARR. Keep the free tier generous, but charge from your production signal early.')
on conflict (n) do update set title = excluded.title, body = excluded.body;

update public.diagnostic_bands set advice = 'You''re probably sales-led or selling infrastructure to enterprises. Read lessons 11, 1, 3 and 8 and skip the rest.' where min_score = 0;

update public.faq set a = 'Three compounding moves. A positioning change that shipped with the Show HN, "the open source Firebase alternative", took databases from 8 to 800 in three days. Relentless shipping, packaged as Launch Weeks, which Copplestone credits with roughly a 20% growth bump each (their effect on GitHub stars faded every year). Then AI app builders and coding agents adopted Supabase as their default backend, and agents now launch most new databases on the platform.' where n = 1;
update public.faq set a = 'Time your onboarding against your main competitor with a stopwatch, then cut it until you''re an order of magnitude faster. It''s cheap, it compounds, and Supabase never even advertised theirs. Second: describe the ideal customer whose usage grows into big bills, and name 20 of those teams. Launch weeks come later, and measure them in signups, not stars.' where n = 8;

-- The lessons index now runs in reading order (by stage) and shows each lesson's target.
update public.case_queries set
  sql = 'select id, title, stage, target
from lessons order by array_position(array[''pre-launch'', ''launch'', ''early-revenue'', ''scale'', ''always''], stage), id;',
  columns = '[{"name": "id", "type": "int4", "format": "mono"}, {"name": "title", "type": "text", "format": "bold"}, {"name": "stage", "type": "text", "format": "mono"}, {"name": "target", "type": "text"}]'::jsonb
where id = 'lessons_index';
